      "id": "q7",
      "operation": "command.exec",
      "resource": "npx -y @midscene/computer@1 assert --prompt \"there is a login button visible\"",
      "summary": "Assert screen state: login button visible",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 168,
