      }
    },
    {
      "id": "q13",
      "operation": "command.exec",
      "resource": "npx -y @midscene/computer@1 record start --displayId 1 --output ./save-observation.json",
      "summary": "Start recording transient UI state on display 1",
      "provenance": {
