        "file": "SKILL.md",
        "line_start": 213,
        "line_end": 214
      }
    },
    {
      "id": "q15",
      "operation": "command.exec",
      "resource": "npx -y @midscene/computer@1 assert --displayId 1 --record ./save-observation.json --prompt \"a saved confirmation appeared\"",
      "summary": "Assert transient UI state from recording on display 1",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 217,
