      "id": "q16",
      "operation": "command.exec",
      "resource": "npx -y @midscene/computer@1 tap --locate '{\"prompt\": \"tap the area contains the image\", \"images\": [{\"name\": \"target image\", \"url\": \"https://github.githubassets.com/assets/GitHub-Mark-ea2971cee799.png\"}], \"convertHttpImage2Base64\": true}'",
      "summary": "Tap on screen area matching a reference image",
      "provenance": {
        "file": "SKILL.md",
