      "id": "q17",
      "operation": "command.exec",
      "resource": "npx -y @midscene/computer@1 disconnect",
      "summary": "Disconnect from desktop session",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 246,
        "line_end": 246
      }
    },
    {
      "id": "q18",
      "operation": "command.exec",
      "resource": "npx -y @midscene/computer@1 report-tool --action to-markdown --htmlPath ./midscene_run/report/.../index.html --outputDir ./output-markdown",
      "summary": "Convert generated HTML report to Markdown format",
